var n=`0135-satsivi`;var t=`world-0135`;var a=`GE`;var o=`western-asia`;var r=4;var s=131;var l={en:`Satsivi`,ua:`Сациві`};var g={en:`A classic dish from Georgia, featuring chicken thigh, yellow onion, walnut, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: куряче стегно, жовта цибуля, волоський горіх, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 42 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 42 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:42,i:[[`chicken-thigh`,750,`g`],[`water`,1350,`ml`],[`yellow-onion`,150,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`walnut`,290,`g`],[`garlic`,5,`clove`],[`ground-coriander`,6,`g`],[`ground-fenugreek`,4,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:12,i:[[`apple-cider-vinegar`,22,`ml`],[`ground-cinnamon`,2,`g`],[`hot-paprika`,3,`g`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 65 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 65 хвилин.`,t:[`rapid-chilling`],m:65,i:[[`parsley`,20,`g`]]}];var m={slug:n,id:t,country:`GE`,region:o,servings:4,minutes:131,title:l,text:g,steps:d};export{a as country,m as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,g as text,l as title};